async function load(p,root) { const bytes=await readFile(`${root}/${p}`);return {bytes,value:JSON.parse(bytes),sha256:hash(bytes)}; }
export async function readOptionalJevbenchV179Release(root=process.cwd()) {
 let publication;
 try {publication=await load(V179_MANIFEST,root);}catch(e){if(e.code==='ENOENT')return null;throw e;}
 const previous=await readOptionalJevbenchV178Release(root);
 const predecessor=await load(`${V179_ROOT}/jevbench-v1.7.8-publication.json`,root);
 const bundle=Object.fromEntries(await Promise.all(V179_FILE_KEYS.map(async k=>[k,await load(`${V179_ROOT}/jevbench-v1.7.9-${k}.json`,root)])));
 for(const [k,v] of Object.entries(bundle))if(v.sha256!==publication.value.files[k]?.sha256)fail('bytes hash '+k);
 for(const k of ['history','history-carry','carry'])if(bundle[k].sha256!==previous.manifest.files[k].sha256)fail('immutable '+k+' bytes');
 validateJevbenchV179Bundle({manifest:publication.value,artifact:bundle.results.value,categories:bundle.categories.value,carry:bundle.carry.value,proof:bundle.proof.value,previous,previousManifestSha256:predecessor.sha256});
 return {artifact:bundle.results.value,bytes:bundle.results.bytes,sha256:bundle.results.sha256,categories:bundle.categories.value,categoriesSha256:bundle.categories.sha256,carry:bundle.carry.value,carrySha256:bundle.carry.sha256,proof:bundle.proof.value,manifest:publication.value,historical:previous.historical};
}
export async function readJevbenchV179ForBoard(root=process.cwd()) {
 let p;try{p=(await load(V179_MANIFEST,root)).value;}catch(e){if(e.code==='ENOENT')return null;throw e;}
 if(p?.review?.verdict!=='PASS')return null;
 return readOptionalJevbenchV179Release(root);
}
export async function hasPublishedJevbenchV179Release(root=process.cwd(),log=console.error) {
 try{return Boolean(await readJevbenchV179ForBoard(root));}catch{log('JevBench v1.7.9 navigation omitted: publication validation failed');return false;}
}
export function v179BoardInput(release){return {artifact:release.artifact,categories:release.categories};}
export function withV179Addendum(chain,release) {
 const bounds={...apiFullAddendumCategoryBounds(chain.categories)};
 for(const k of V179_CHANGED_KEYS) {
  const row=release.artifact.systems.find(s=>s.key===k);
  const counts=new Map();
  for(const s of chain.published.systems)if(s.draw?.id===row.draw.id && bounds[s.key]){const b=JSON.stringify(bounds[s.key]);counts.set(b,(counts.get(b)??0)+1);}
  const [best]=[...counts].sort((a,b)=>b[1]-a[1]);if(!best)fail('category bounds '+k);
  bounds[k]=JSON.parse(best[0]);
 }
 const update=a=>({...a,systems:release.artifact.systems,board:release.artifact.board,n_ranked:release.artifact.n_ranked,roster_count:release.artifact.roster_count,measurement_notes:release.artifact.measurement_notes,restated_by:'v1.7.9',v179_sha256:release.sha256});
 const categories=withRowPoolCategoryRows({...release.categories,revision:chain.published.revision,restated_by:'v1.7.9',systems:{}},release.categories.systems,bounds);
 return {...chain,published:update(chain.published),merged:update(chain.merged),categories,publishedCarry:release.carry};
}
